console.log("A lattice is a discrete grid in R^n:");
console.log("  L = {integer combinations of basis vectors}\n");

console.log("Key concepts:");
console.log("  - Basis: generators of the lattice (not unique)");
console.log("  - Determinant: volume, invariant under basis change");
